/**
 * lib/library/bookPlates — B-BOOK-01: the plate registry of the new kid
 * library (lane B §4.8: a registry beside kidThemeManifest, not an extension
 * of it). One entry per scene plate: a 3:2 master (1536x1024 WebP), child-free
 * and text-free, at `public/visuals/books/<bookId>/<plateId>.webp`.
 *
 * Provenance is recorded per plate and starts EMPTY: a plate is only proven
 * child-free / text-free when Fable has viewed it (lane B §4.9). Until the
 * real plates exist, the DEV build falls back to a flat placeholder plate at
 * `public/_dev/plates/<bookId>/<plateId>.webp` (generated by
 * scripts/dev-book-placeholders.py; `public/_dev/` is git-ignored). The
 * production build never resolves a placeholder.
 *
 * No imports from api/* — reading a book makes no request but static files.
 */

export type LightRig = "morning" | "day" | "golden" | "dusk" | "night";

export interface BookPlate {
  id: string;
  bookId: string;
  /** Public URL of the real master plate. */
  file: string;
  width: number;
  height: number;
  light: LightRig;
  /** Optional foreground occluder (alpha WebP, same box as the master). */
  fg?: string;
  provenance: {
    childFree: boolean;
    textFree: boolean;
    /** Who viewed the plate full size (lane B §4.9); null = not yet viewed. */
    reviewedBy: string | null;
  };
}

/** The master plate size every book plate is authored at. */
export const PLATE_MASTER = { width: 1536, height: 1024 } as const;

const UNREVIEWED = { childFree: false, textFree: false, reviewedBy: null } as const;

function plate(bookId: string, id: string, light: LightRig): BookPlate {
  return {
    id,
    bookId,
    file: `/visuals/books/${bookId}/${id}.webp`,
    width: PLATE_MASTER.width,
    height: PLATE_MASTER.height,
    light,
    provenance: { ...UNREVIEWED },
  };
}

const ABRAM = "abrams-long-road";

/** Lane A §6.3 plate ledger: 9 plates for "Abram's Long Road". */
export const BOOK_PLATES: Readonly<Record<string, Readonly<Record<string, BookPlate>>>> = {
  [ABRAM]: {
    P1e: plate(ABRAM, "P1e", "dusk"), // Haran by the well, evening
    P1m: plate(ABRAM, "P1m", "morning"), // the same, morning, packing
    P1b: plate(ABRAM, "P1b", "day"), // + the line waiting in hot sun, goats in the barley
    P1c: plate(ABRAM, "P1c", "morning"), // + the little donkey and the treasure pile
    P2: plate(ABRAM, "P2", "night"), // Haran at night, tent flap and star field
    P3: plate(ABRAM, "P3", "morning"), // the road at sunrise
    P4: plate(ABRAM, "P4", "day"), // the great river with stepping stones
    P5: plate(ABRAM, "P5", "golden"), // the hill with the great oak
    P6: plate(ABRAM, "P6", "dusk"), // the new tent and stone altar under the oak
  },
};

export function getPlate(bookId: string, plateId: string): BookPlate | undefined {
  return BOOK_PLATES[bookId]?.[plateId];
}

/** The DEV placeholder for a plate (never committed, never in production). */
export function devPlaceholderPath(bookId: string, plateId: string): string {
  return `/_dev/plates/${bookId}/${plateId}.webp`;
}

/** The sources to try, in order: the real plate, then (DEV only) the
 *  placeholder. The renderer advances on an image error, so a missing real
 *  file falls back without a request to anything but static files. */
export function plateSources(p: BookPlate, opts: { dev: boolean }): string[] {
  return opts.dev ? [p.file, devPlaceholderPath(p.bookId, p.id)] : [p.file];
}
